/* v7: Kevin Mindmap-inspired mother/child map; card typography remains v3/v5 */
.qy-mindmap{
  margin-top:10px;
  padding:12px;
  background:#fafafa;
  border-radius:10px;
  overflow:hidden;
}
.qy-mm-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  margin-bottom:8px;
}
.qy-mm-title{
  font-size:13px;
  font-weight:800;
  color:#555;
}
.qy-mm-count{
  font-size:11px;
  color:#9aa0a6;
  white-space:nowrap;
}
.qy-mm-svg{
  display:block;
  width:100%;
  min-height:180px;
  overflow:visible;
  touch-action:manipulation;
}
.qy-mm-status{
  min-height:16px;
  margin-top:5px;
  font-size:11px;
  color:#9aa0a6;
}
.qy-mm-legacy-text{
  padding:10px 0 2px;
  font-size:12px;
  color:#9aa0a6;
  line-height:1.7;
}
.qy-mm-link{
  fill:none;
  stroke:#c9cdd2;
  stroke-width:1.5;
}
.qy-mm-node rect{
  fill:#fff;
  stroke:#dfe3e7;
  stroke-width:1.2;
}
.qy-mm-node.branch rect{
  fill:#f4f5f6;
  stroke:#d8dce0;
}
.qy-mm-node.current rect{
  fill:#222;
  stroke:#222;
}
.qy-mm-node text{
  fill:#555;
  font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei","Noto Sans CJK SC",sans-serif;
  font-size:12px;
  pointer-events:none;
}
.qy-mm-node .sub{
  fill:#a0a4aa;
  font-size:10px;
}
.qy-mm-node.current text,
.qy-mm-node.current .sub{
  fill:#fff;
}
.qy-mm-node.leaf{
  cursor:pointer;
}
.qy-mm-node.leaf:hover rect{
  stroke:#555;
}
.qy-mm-node.leaf:active rect{
  fill:#eee;
}
.qy-mm-node.current:active rect{
  fill:#222;
}
@media(max-width:600px){
  .qy-mindmap{padding:10px}
  .qy-mm-title{font-size:12px}
  .qy-mm-count{font-size:10px}
}
/* v8 metadata badges */
.meta-badges{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 3px}
.meta-badge{display:inline-flex;align-items:center;padding:3px 8px;border:1px solid #e2e5e9;border-radius:999px;background:#fff;color:#777;font-size:11px;line-height:1.35}
.meta-badge.year-badge{background:#222;color:#fff;border-color:#222;font-weight:800}
.meta-badge.point-badge{background:#f7f7f7;color:#555}
.meta-badge.exam-badge,.meta-badge.type-badge{color:#8a8f98}
.qy-mindmap.static{overflow:auto}
.qy-mindmap.static .qy-mm-svg{display:block;width:100%;height:auto;min-height:0;overflow:visible;touch-action:manipulation}
.qy-mindmap.static .qy-mm-node.leaf{cursor:pointer}
.qy-mindmap.static .qy-mm-node.root rect{fill:#f1f3f4;stroke:#d8dce0}
.qy-mindmap.static .qy-mm-node.root text{font-weight:800}
.qy-mindmap.static .qy-mm-node.root .sub{font-weight:400}
@media(max-width:600px){.meta-badge{font-size:10px;padding:3px 7px}}

/* v4.8 全平台统一母子题查看器 */
.qy-mobile-modal{
  position:fixed; inset:0; z-index:99999;
  display:none; align-items:flex-end; justify-content:center;
  background:rgba(0,0,0,.28);
  padding:12px;
  box-sizing:border-box;
}
.qy-mobile-modal.open{display:flex}
.qy-mobile-sheet{
  width:min(760px,100%);
  max-height:88vh;
  overflow:auto;
  background:#fff;
  border:1px solid #e5e7eb;
  border-radius:18px;
  box-shadow:0 18px 60px rgba(0,0,0,.18);
  padding:16px;
  box-sizing:border-box;
}
.qy-mobile-head{
  position:sticky; top:-16px; z-index:2;
  display:flex; align-items:flex-start; justify-content:space-between; gap:12px;
  margin:-16px -16px 14px; padding:14px 16px 12px;
  background:rgba(255,255,255,.96);
  border-bottom:1px solid #eef0f2;
  backdrop-filter:blur(12px);
}
.qy-mobile-kicker{font-size:10px;color:#9aa0a6;font-weight:700;letter-spacing:.06em}
.qy-mobile-title{margin-top:3px;font-size:17px;font-weight:900;color:#222}
.qy-mobile-close{
  flex:0 0 auto;width:34px;height:34px;border:0;border-radius:50%;
  background:#f1f3f4;color:#555;font-size:24px;line-height:32px;padding:0;
}
.qy-mobile-meta{font-size:11px;color:#999;margin-bottom:10px}
.qy-mobile-question{font-size:17px;line-height:1.75;font-weight:700;color:#222;margin-bottom:12px}
.qy-mobile-options .option{margin-bottom:8px}
.qy-mobile-answer{margin-top:14px}
.qy-mobile-reveal{
  width:100%;margin-top:14px;padding:11px 14px;
  border:1px solid #dfe3e7;border-radius:11px;background:#f7f8f9;
  color:#333;font-size:14px;font-weight:800;
}
.mobile .qy-mm-status{color:#777}
.mobile .qy-mindmap.static .qy-mm-node.leaf:active rect{fill:#e7e9ec}
@media(min-width:700px){
  .qy-mobile-modal{align-items:center}
  .qy-mobile-sheet{border-radius:16px}
}

.qy-analysis-table{width:100%;border-collapse:collapse;margin:10px 0;font-size:14px}.qy-analysis-table td{border:1px solid #e2e5e9;padding:7px 9px;vertical-align:top}

.anki-audio, .anki-video { display: block; width: 100%; max-width: 100%; margin: 0.5rem 0; }
.anki-media-missing { display: block; margin: 0.35rem 0; color: #9f1239; font-size: 0.875rem; }
.anki-math-source,
.anki-math-rendered {
  display: inline-block;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  vertical-align: middle;
  -webkit-overflow-scrolling: touch;
}
.anki-math-source {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  white-space: pre-wrap;
}
.anki-math-source[data-anki-math="display"],
.anki-math-rendered[data-anki-math="display"] {
  display: block;
  margin: 0.75rem 0;
  text-align: center;
}
.anki-math-rendered math {
  max-width: 100%;
}
@media (max-width: 767px) {
  .anki-math-source,
  .anki-math-rendered {
    width: 100%;
    max-width: 100%;
    text-align: left;
  }
}
